const batchIdInput = document.getElementById('batch-id');
const batchRequestsInput = document.getElementById('batch-requests');
const batchMessage = document.getElementById('batch-message');
const batchResult = document.getElementById('batch-result');

function exampleBatchRequests() {
  const suffix1 = crypto.randomUUID ? crypto.randomUUID().slice(0, 8) : String(Date.now());
  const suffix2 = crypto.randomUUID ? crypto.randomUUID().slice(-8) : String(Date.now() + 1);
  return [
    { request_id: `req-${suffix1}`, dataset_id: 'retail-demo', filters: { region: 'north' }, epsilon: 0.3 },
    { request_id: `req-${suffix2}`, dataset_id: 'retail-demo', filters: null, epsilon: 0.2 },
  ];
}

function fillBatchExample() {
  batchIdInput.value = `batch-${crypto.randomUUID ? crypto.randomUUID().slice(0, 8) : Date.now()}`;
  batchRequestsInput.value = JSON.stringify(exampleBatchRequests(), null, 2);
}

document.getElementById('batch-example-button').addEventListener('click', fillBatchExample);
fillBatchExample();

function renderBatchResult(data, replayed) {
  batchResult.textContent = '';
  const summary = document.createElement('div');
  summary.className = 'batch-summary';
  summary.textContent = `${replayed ? '重放首次响应（未采样、未扣费）' : '整批已提交'} · ${data.releases.length} 条 · 合计 ε=${data.total_epsilon} · 最终剩余预算 ${data.remaining_budget} · ${new Date(data.created_at).toLocaleString()}`;
  batchResult.append(summary);
  data.releases.forEach((release, index) => {
    const card = document.createElement('div');
    card.className = 'batch-item';
    const head = document.createElement('div');
    head.className = 'batch-item-head';
    const order = document.createElement('strong');
    order.textContent = `#${index + 1} 计数 ${release.published_count}`;
    const rid = document.createElement('span');
    rid.className = 'muted';
    rid.textContent = `request_id=${release.request_id}`;
    const filters = document.createElement('span');
    filters.className = 'muted';
    filters.textContent = describeFilters(release.filters);
    const eps = document.createElement('span');
    eps.className = 'muted';
    eps.textContent = `ε=${release.epsilon}，扣后余额 ${release.remaining_budget}`;
    head.append(order, rid, filters, eps);
    card.append(head);
    batchResult.append(card);
  });
}

document.getElementById('batch-form').addEventListener('submit', async (event) => {
  event.preventDefault();
  const button = document.getElementById('batch-publish-button');
  batchMessage.className = '';
  batchMessage.textContent = '';
  batchResult.textContent = '';
  const batchId = batchIdInput.value.trim();
  let requests;
  try {
    requests = JSON.parse(batchRequestsInput.value);
  } catch (error) {
    batchMessage.className = 'error';
    batchMessage.textContent = `批量发布失败：requests 不是合法 JSON（${error.message}）。`;
    return;
  }
  if (!Array.isArray(requests) || requests.length < 1 || requests.length > 20) {
    batchMessage.className = 'error';
    batchMessage.textContent = '批量发布失败：requests 必须是包含 1–20 项的 JSON 数组。';
    return;
  }
  if (!batchId) {
    batchMessage.className = 'error';
    batchMessage.textContent = '批量发布失败：batch_id 必须是非空字符串。';
    return;
  }
  const payload = { batch_id: batchId, requests };
  button.disabled = true;
  try {
    const response = await fetch('/api/releases/batch', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const data = await response.json().catch(() => null);
    if (!response.ok) {
      batchMessage.className = 'error';
      batchMessage.textContent = `批量发布失败：${formatError(data, response.status)}`;
      return;
    }
    batchMessage.className = 'success';
    batchMessage.textContent = response.status === 200
      ? '该 batch_id 已提交过，返回首次响应。'
      : '整批发布成功。';
    renderBatchResult(data, response.status === 200);
    await Promise.all([refreshBudget(), refreshHistory()]);
  } catch (error) {
    batchMessage.className = 'error';
    batchMessage.textContent = `批量发布失败：${error.message}`;
  } finally {
    button.disabled = false;
  }
});

